type ChromeWtCloseFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
}

// chrome_wt_close(id, code, reason)
//
// Results: (ret, error).
func (c *Client) ChromeWtClose(p_id uint64, p_code uint32, p_reason string) (int32, error) {
	f, err := c.ChromeWtCloseAsync(p_id, p_code, p_reason)
	if err != nil {
		return 0, err
	}
	return f.Wait()
}

func (c *Client) ChromeWtCloseAsync(p_id uint64, p_code uint32, p_reason string) (ChromeWtCloseFuture, error) {
	if err := rt.CheckStr(p_reason, 1024); err != nil {
		return ChromeWtCloseFuture{}, err
	}
	// G1: id u64 @0, code u32 @8; V1: reason from 16.
	// RESP_BOUND = G2pad 4 (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpChromeWtClose, 16+rt.StrWire(len(p_reason)), 4)
	if err != nil {
		return ChromeWtCloseFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint64(body[0:], p_id)
	hqqLE.PutUint32(body[8:], p_code)
	clear(body[12:16])
	rt.PutStr(body, 16, p_reason)
	call, err := c.c.Submit(e)
	if err != nil {
		return ChromeWtCloseFuture{}, err
	}
	return ChromeWtCloseFuture{c, call, call.ID()}, nil
}

func (f ChromeWtCloseFuture) Wait() (int32, error) {
	if f.c == nil {
		return 0, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return 0, err
	}
	defer d.Release()
	// G2: ret i32 @0 (size 4).
	if len(d.Body) != 4 || d.Fail {
		return 0, d.Malformed()
	}
	return int32(hqqLE.Uint32(d.Body[0:])), nil
}
